pub fn rebalance_step_to_proto(v: &crate::rebalance::RebalanceStep) -> v1::MfRebalanceStep {
    let kind = match v {
        crate::rebalance::RebalanceStep::LoadTarget { shard_id, replica_id, node_id, load_version } => v1::mf_rebalance_step::Kind::LoadTarget(v1::MfRebalanceStepLoadTarget { shard_id: *shard_id, replica_id: *replica_id, node_id: *node_id, load_version: *load_version }),
        crate::rebalance::RebalanceStep::ReloadTarget { shard_id, replica_id, node_id, load_version } => v1::mf_rebalance_step::Kind::ReloadTarget(v1::MfRebalanceStepReloadTarget { shard_id: *shard_id, replica_id: *replica_id, node_id: *node_id, load_version: *load_version }),
        crate::rebalance::RebalanceStep::UpdateMembership { shard_id, active_replica_ids, primary_replica_id, membership_version } => v1::mf_rebalance_step::Kind::UpdateMembership(v1::MfRebalanceStepUpdateMembership { shard_id: *shard_id, active_replica_ids: active_replica_ids.iter().map(|x| *x).collect(), primary_replica_id: *primary_replica_id, membership_version: *membership_version }),
        crate::rebalance::RebalanceStep::FreezeSource { shard_id, replica_id, node_id } => v1::mf_rebalance_step::Kind::FreezeSource(v1::MfRebalanceStepFreezeSource { shard_id: *shard_id, replica_id: *replica_id, node_id: *node_id }),
        crate::rebalance::RebalanceStep::UnloadSource { shard_id, replica_id, node_id } => v1::mf_rebalance_step::Kind::UnloadSource(v1::MfRebalanceStepUnloadSource { shard_id: *shard_id, replica_id: *replica_id, node_id: *node_id }),
    };
    v1::MfRebalanceStep { kind: Some(kind) }
}

pub fn rebalance_step_from_proto(m: v1::MfRebalanceStep) -> Result<crate::rebalance::RebalanceStep, String> {
    match m.kind.ok_or_else(|| "RebalanceStep has no variant set".to_string())? {
        v1::mf_rebalance_step::Kind::LoadTarget(x) => Ok(crate::rebalance::RebalanceStep::LoadTarget { shard_id: Ok::<_, String>(x.shard_id)?, replica_id: Ok::<_, String>(x.replica_id)?, node_id: Ok::<_, String>(x.node_id)?, load_version: Ok::<_, String>(x.load_version)? }),
        v1::mf_rebalance_step::Kind::ReloadTarget(x) => Ok(crate::rebalance::RebalanceStep::ReloadTarget { shard_id: Ok::<_, String>(x.shard_id)?, replica_id: Ok::<_, String>(x.replica_id)?, node_id: Ok::<_, String>(x.node_id)?, load_version: Ok::<_, String>(x.load_version)? }),
        v1::mf_rebalance_step::Kind::UpdateMembership(x) => Ok(crate::rebalance::RebalanceStep::UpdateMembership { shard_id: Ok::<_, String>(x.shard_id)?, active_replica_ids: x.active_replica_ids.into_iter().map(|x| Ok::<_, String>(x)).collect::<Result<Vec<_>, String>>()?, primary_replica_id: Ok::<_, String>(x.primary_replica_id)?, membership_version: Ok::<_, String>(x.membership_version)? }),
        v1::mf_rebalance_step::Kind::FreezeSource(x) => Ok(crate::rebalance::RebalanceStep::FreezeSource { shard_id: Ok::<_, String>(x.shard_id)?, replica_id: Ok::<_, String>(x.replica_id)?, node_id: Ok::<_, String>(x.node_id)? }),
        v1::mf_rebalance_step::Kind::UnloadSource(x) => Ok(crate::rebalance::RebalanceStep::UnloadSource { shard_id: Ok::<_, String>(x.shard_id)?, replica_id: Ok::<_, String>(x.replica_id)?, node_id: Ok::<_, String>(x.node_id)? }),
    }
}

